class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = []  # list of option strings in order they were added
        self.votes = {}  # voter -> option mapping
        self.option_counts = {}  # option -> vote count mapping

    def add_option(self, option: str) -> None:
        if option not in self.options:
            self.options.append(option)
            self.option_counts[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self.options:
            raise ValueError(f"Option '{option}' does not exist")
        if voter in self.votes:
            raise ValueError(f"Voter '{voter}' has already voted")

        self.votes[voter] = option
        self.option_counts[option] += 1

    def winner(self) -> str | None:
        if len(self.votes) < 3:
            return None

        if not self.options:
            return None

        # Find the maximum vote count
        max_count = max(self.option_counts.values())

        # Find all options with the maximum count
        tied_options = [opt for opt in self.options if self.option_counts[opt] == max_count]

        # Return the one that was added last (last in the options list)
        return tied_options[-1] if tied_options else None
